grid{display:grid;grid-template-columns:repeat(3,1fr);gap:35px;padding:31px 0}.brand-values-grid>div{display:flex;flex-direction:column;gap:8px}.brand-values strong{font:400 25px Georgia,serif}.brand-values span{font-size:12px;line-height:1.6;color:#657265}.brand-line{padding:100px 0 115px;background:#faf8f3}.brand-line-header{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:end;margin-bottom:34px}.brand-line-header>p{line-height:1.8;color:#607060}.brand-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.brand-model{border:1px solid #e1d8c8;background:#fff;overflow:hidden}.brand-model-art{height:290px;display:grid;place-items:center;position:relative;isolation:isolate;background:linear-gradient(135deg,#4d7e6b,#18352a)}.brand-model-art[data-tone=blue]{background:linear-gradient(135deg,#88adb9,#253f53)}.brand-model-art[data-tone=black]{background:linear-gradient(135deg,#595e5a,#171c19)}.brand-mini-band{height:257px;width:93px;border-radius:15px;position:absolute;background:linear-gradient(90deg,#52675b,#d5ddd0 25%,#6c8275 51%,#d5decf 75%,#52675b);transform:rotate(-17deg)}.brand-mini-case{width:171px;height:171px;position:relative;border:9px solid #dfc99f;border-radius:50%;background:radial-gradient(circle at 29% 24%,#63a486,#123e2d 76%);transform:rotate(-17deg);box-shadow:0 0 0 3px #917a50,15px 21px 30px #0005}.brand-model-art[data-tone=blue] .brand-mini-case{background:radial-gradient(circle at 29% 24%,#b1dae5,#28576d 76%)}.brand-model-art[data-tone=black] .brand-mini-case{background:radial-gradient(circle at 29% 24%,#626a60,#18211a 76%)}.brand-mini-case:before,.brand-mini-case:after{content:'';position:absolute;bottom:50%;left:50%;background:#f3dfb5;transform-origin:bottom center}.brand-mini-case:before{height:43px;width:4px;transform:rotate(40deg)}.brand-mini-case:after{height:59px;width:3px;transform:rotate(-105deg)}.brand-mini-case>span{position:absolute;top:30px;left:50%;transform:translateX(-50%);font:400 10px Georgia,serif;color:#e8d4a6;white-space:nowrap}.brand-mini-mark{position:absolute;bottom:14px;left:15px;color:#f2eddf;background:#18281cab;font-size:10px;letter-spacing:.08em;padding:7px}.brand-model-text{padding:24px}.brand-model-text small{color:#a18358;font-weight:700;letter-spacing:.14em;text-transform:uppercase;font-size:10px}.brand-model-text h3{font:400 28px Georgia,serif;margin:10px 0}.brand-model-text p{font-size:14px;line-height:1.76;color:#5e6a60}.brand-model-text dl{border-top:1px solid #e8e1d3;padding-top:15px;display:grid;grid-template-columns:1fr;gap:12px}.brand-model-text dl>div{display:flex;justify-content:space-between;gap:12px}.brand-model-text dt{color:#6e766e;font-size:12px}.brand-model-text dd{margin:0;text-align:right;color:#314c36;font-size:12px;font-weight:650}.brand-model-text button{margin-top:17px;background:#203c2d;color:#fff;padding:12px 15px;border:1px solid #203c2d;cursor:pointer;font:600 12px system-ui;width:100%}.brand-model-text button[aria-pressed=true]{background:#eae0c8;color:#203c2d}.brand-disclaimer{margin-top:31px;padding:21px;background:#efe6d5;color:#596755;font-size:13px;line-height:1.8}.brand-disclaimer strong{color:#213b2b}.brand-quality{padding:105px 0;background:#223c2f;color:#fff}.brand-quality-grid{display:grid;grid-template-columns:1fr 1fr;gap:62px}.brand-quality h2{color:#fff}.brand-quality-grid>div:first-child p:not(.overline){line-height:1.9;color:#d6dfd2}.brand-steps{display:grid;grid-template-columns:1fr 1fr;gap:11px}.brand-steps>div{border:1px solid #617867;padding:25px}.brand-steps span{font:400 29px Georgia,serif;color:#d9c294}.brand-steps strong{display:block;font:400 21px Georgia,serif;margin-top:13px}.brand-steps p{font-size:12px;line-height:1.7;color:#ccd9cd}.brand-custom{padding:95px 0;background:#f0ebe1}.brand-custom-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:37px}.brand-custom article{background:#faf8f3;border:1px solid #ded5c6;padding:35px}.brand-symbol{font:400 40px Georgia,serif;color:#9a7f5c}.brand-custom h3{font:400 28px Georgia,serif;margin:14px 0}.brand-custom p{font-size:14px;line-height:1.8;color:#647165}.brand-status{text-align:center;background:#203529;color:#fff;padding:100px 0}.brand-status h2{color:#fff;margin-bottom:22px}.brand-status p:not(.overline){max-width:670px;color:#d3dfd3;line-height:1.8;margin:0 auto 28px}
