'use strict';
(()=>{
 const products=[
 {id:'atelier-emeraude',name:'Émeraude',tone:'green',style:'Signature sport chic',detail:'Cadran vert profond, bracelet intégré à maillons. Notre premier choix pour une montre affirmée mais équilibrée.',case:'Acier à vérifier',movement:'Quartz à confirmer',brand:'Logo discret à 12 h'},
 {id:'atelier-glacier',name:'Glacier',tone:'blue',style:'Lumineuse et moderne',detail:'Cadran bleu glacier, finition argentée et indices simples. Une ligne contemporaine et polyvalente.',case:'Acier à vérifier',movement:'Quartz à confirmer',brand:'Couleur et logo usine'},
 {id:'atelier-minuit',name:'Minuit',tone:'black',style:'Luxe discret',detail:'Noir profond, boîtier fin et lignes sobres pour une pièce facile à porter en toutes circonstances.',case:'Métal et revêtement à vérifier',movement:'Quartz à confirmer',brand:'Logo ton sur ton'}
 ];
 const container=document.getElementById('brandModels');
 if(!container)return;
 const key='atelier-custom-concepts-v1';
 let selected=new Set();
 try{const x=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(x))selected=new Set(x.filter(t=>products.some(p=>p.id===t)))}catch(_){}
 const node=(tag,cls,val)=>{const d=document.createElement(tag);if(cls)d.className=cls;if(val!==undefined)d.textContent=val;return d};
 function render(){
   container.replaceChildren(...products.map(p=>{
     const card=node('article','brand-model');
     const art=node('div','brand-model-art');art.dataset.tone=p.tone;art.setAttribute('role','img');art.setAttribute('aria-label','Illustration du concept '+p.name+', pas un produit réel');
     const strap=node('div','brand-mini-band'),dial=node('div','brand-mini-case');
     dial.append(node('span','','A · M'));art.append(strap,dial,node('span','brand-mini-mark','CONCEPT • MARQUE PROVISOIRE'));
     const body=node('div','brand-model-text');
     body.append(node('small','',p.style),node('h3','',p.name),node('p','',p.detail));
     const dl=node('dl');
     for(const [label,val] of [['Boîtier',p.case],['Mouvement',p.movement],['Personnalisation',p.brand]]){const row=node('div');row.append(node('dt','',label),node('dd','',val));dl.append(row)}
     body.append(dl);
     const btn=node('button','',selected.has(p.id)?'✓ Style retenu':'♡ Garder ce style en favori');
     btn.type='button';btn.setAttribute('aria-pressed',String(selected.has(p.id)));
     btn.addEventListener('click',()=>{selected.has(p.id)?selected.delete(p.id):selected.add(p.id);try{localStorage.setItem(key,JSON.stringify([...selected]))}catch(_){}render()});
     body.append(btn);card.append(art,body);return card;
   }));
 }
 render();
})();

/* Atelier Montres · genuine-watch photographic viewer */
.am-photo-dialog{position:fixed;inset:0;width:min(1020px,calc(100vw - 30px));max-width:1020px;max-height:min(95dvh,950px);margin:auto;padding:0;border:1px solid #c6ae83;background:#f8f6ef;color:#20392a;box-shadow:0 32px 90px #09150cc2;overflow:auto;overscroll-behavior:contain}
.am-photo-dialog::backdrop{background:#07120bd9;backdrop-filter:blur(7px)}
.am-photo-top{padding:17px 24px;background:#172e22;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:16px}
.am-photo-meta{min-width:0}
.am-photo-kicker{font:700 9px/1.4 system-ui,sans-serif;letter-spacing:.2em;color:#d8b987;margin:0 0 5px}
.am-photo-title{font:400 clamp(19px,3vw,30px)/1.2 Georgia,serif;color:#fff;overflow-wrap:anywhere;margin:0}
.am-photo-close{width:44px;height:44px;flex:none;border:1px solid #e1cfaf66;border-radius:50%;background:transparent;color:#fff;font:400 30px/1 system-ui;cursor:pointer}
.am-photo-canvas{height:clamp(300px,59dvh,650px);background:radial-gradient(circle at center,#fffefa 0%,#eeeae1 80%);position:relative;display:flex;align-items:center;justify-content:center;overflow:auto;overscroll-behavior:contain;padding:16px}
.am-photo-large{width:auto;height:auto;max-height:100%;max-width:100%;object-fit:contain;mix-blend-mode:multiply;filter:drop-shadow(0 15px 25px #071c1324);transition:width .18s ease,max-width .18s ease}
.am-photo-canvas.am-photo-expanded{justify-content:flex-start;align-items:flex-start}
.am-photo-canvas.am-photo-expanded .am-photo-large{max-width:none;max-height:none;width:175%;height:auto;margin:auto}
.am-photo-status{max-width:250px;text-align:center;font-size:13px;color:#617063}
.am-photo-bottom{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap;padding:17px 22px 8px}
.am-photo-bottom button,.am-photo-official{font:650 12px system-ui,sans-serif;border:1px solid #c9c2b3;background:#fffefa;color:#23432f;padding:11px 15px;min-height:44px;cursor:pointer;border-radius:2px;text-decoration:none}
.am-photo-bottom button:hover,.am-photo-official:hover{background:#e7e8df}
.am-photo-bottom button:disabled{opacity:.4;cursor:default}
.am-photo-position{font-size:12px;letter-spacing:.12em;color:#6d756e;min-width:43px;text-align:center}
.am-photo-official{background:#244532;color:#fff;border-color:#244532}
.am-photo-official:hover{background:#315740;color:#fff}
.am-photo-note{padding:0 24px 14px;color:#737b71;font-size:10px;line-height:1.6;text-align:center;margin:5px 0 0}
.aff-illustration{overflow:hidden}
.aff-photo-expand{position:absolute;inset:0;z-index:4;border:0;background:transparent;color:#263f31;cursor:zoom-in;display:flex;align-items:flex-end;justify-content:flex-end;padding:14px}
.aff-photo-expand span{background:#fffefaeb;border:1px solid #e0d6c6;padding:8px 11px;box-shadow:0 4px 12px #14231b16;font:700 10px system-ui,sans-serif;letter-spacing:.03em}
.aff-photo-expand:hover span,.aff-photo-expand:focus-visible span{background:#244532;color:#fff}
.aff-photo-expand:focus-visible{outline:3px solid #d7af70;outline-offset:-3px}
.aff-card .aff-illustration:has(.aff-photo-expand) .aff-art-label{pointer-events:none}
.detail-photo-expand{min-height:44px;border:1px solid #c2b79f;background:#fffdf7;color:#234531;font:700 12px system-ui,sans-serif;padding:12px 18px;cursor:zoom-in;margin:12px 0 2px}
.detail-photo-expand:hover{background:#294c36;color:#fff}
@media(max-width:650px){
 .am-photo-dialog{width:calc(100vw - 12px);max-height:96dvh}
 .am-photo-top{padding:12px 14px}
 .am-photo-canvas{height:clamp(280px,54dvh,560px)}
 .am-photo-bottom{gap:7px;padding:12px 9px 7px}
 .am-photo-bottom button,.am-photo-official{font-size:11px;padding:9px 11px}
 .am-photo-note{padding-inline:12px}
}
@media(prefers-reduced-motion:reduce){.am-photo-large{transition:none}}

'use strict';
/* One locally sourced, keyboard- and touch-accessible photographic viewer. */
(() => {
  if (window.AtelierPhoto) return;
  const el=(tag,cls,label)=>{
    const n=document.createElement(tag);
    if(cls)n.className=cls;
    if(label!==undefined)n.textContent=label;
    return n;
  };
  let items=[],index=0,loaded=false,expanded=false,initialTouch=null;
  const dialog=el('dialog','am-photo-dialog');
  dialog.id='amPhotoDialog';
  dialog.setAttribute('aria-label','Visionneuse de photographies des montres');
  const top=el('div','am-photo-top'),meta=el('div','am-photo-meta');
  const kicker=el('p','am-photo-kicker','LA COLLECTION · PHOTO AUTHENTIQUE');
  const title=el('h2','am-photo-title');
  const close=el('button','am-photo-close','×');
  close.type='button';close.setAttribute('aria-label','Fermer la photo');
  meta.append(kicker,title);top.append(meta,close);
  const canvas=el('div','am-photo-canvas');
  const photo=el('img','am-photo-large');
  photo.alt='';photo.decoding='async';photo.loading='eager';
  const message=el('p','am-photo-status','Chargement de la photographie…');
  message.setAttribute('role','status');
  canvas.append(photo,message);
  const bottom=el('div','am-photo-bottom');
  const prev=el('button','am-photo-prev','← Précédente');
  const next=el('button','am-photo-next','Suivante →');
  const zoom=el('button','am-photo-zoom','Agrandir ×2');
  const position=el('span','am-photo-position');
  const link=el('a','am-photo-official','Fiche fabricant ↗');
  link.target='_blank';link.rel='noopener noreferrer nofollow';
  for(const b of [prev,next,zoom]) b.type='button';
  bottom.append(prev,position,next,zoom,link);
  const note=el('p','am-photo-note','Photographies des références exactes · images et tarifs non contractuels.');
  dialog.append(top,canvas,bottom,note);
  const source=p=>{
    const t=p.photoReview||{};
    if(t.localUrl==='./assets/watches/'+p.id+'.webp')return t.localUrl;
    if(typeof t.url==='string'&&t.url.startsWith('https://'))return t.url;
    return null;
  };
  const render=()=>{
    const p=items[index];
    if(!p)return;
    const url=source(p);
    title.textContent=p.brand+' · '+p.model;
    position.textContent=(index+1)+' / '+items.length;
    prev.disabled=items.length<2;next.disabled=items.length<2;
    expanded=false;canvas.classList.remove('am-photo-expanded');
    zoom.textContent='Agrandir ×2';zoom.disabled=!url;
    photo.hidden=true;loaded=false;message.hidden=false;
    message.textContent=url?'Chargement de la photographie…':'Photographie indisponible. Consultez le fabricant.';
    photo.alt='Photographie authentique de '+p.brand+' '+p.model;
    if(url){photo.onload=()=>{loaded=true;photo.hidden=false;message.hidden=true};
      photo.onerror=()=>{loaded=false;photo.hidden=true;message.hidden=false;message.textContent='Photo indisponible. Voir la fiche fabricant.'};
      photo.src=url;
    }else photo.removeAttribute('src');
    const raw=p.officialUrl;
    try{const u=new URL(raw);link.href=u.protocol==='https:'?u.href:'#'}catch(_){link.href='#'}
  };
  const navigate=delta=>{if(items.length<2)return;index=(index+delta+items.length)%items.length;render()};
  close.addEventListener('click',()=>dialog.close());
  prev.addEventListener('click',()=>navigate(-1));
  next.addEventListener('click',()=>navigate(1));
  zoom.addEventListener('click',()=>{if(!loaded)return;expanded=!expanded;canvas.classList.toggle('am-photo-expanded',expanded);zoom.textContent=expanded?'Réduire ×1':'Agrandir ×2'});
  dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
  dialog.addEventListener('keydown',event=>{
    if(event.key==='ArrowLeft'){event.preventDefault();navigate(-1)}
    if(event.key==='ArrowRight'){event.preventDefault();navigate(1)}
  });
  canvas.addEventListener('touchstart',event=>{if(event.touches.length===1)initialTouch=event.touches[0].clientX},{passive:true});
  canvas.addEventListener('touchend',event=>{
    if(initialTouch===null||expanded||!event.changedTouches.length){initialTouch=null;return}
    const delta=event.changedTouches[0].clientX-initialTouch;initialTouch=null;
    if(Math.abs(delta)>65)navigate(delta>0?-1:1);
  },{passive:true});
  dialog.addEventListener('close',()=>{photo.onload=null;photo.onerror=null;expanded=false;canvas.classList.remove('am-photo-expanded')});
  document.body.append(dialog);
  window.AtelierPhoto={
    open(collection,id){
      if(!Array.isArray(collection)||!collection.length)return;
      items=collection.filter(p=>p&&typeof p.id==='string'&&typeof p.brand==='string'&&typeof p.model==='string');
      if(!items.length)return;
      index=Math.max(0,items.findIndex(p=>p.id===id));
      render();
      if(typeof dialog.showModal==='function'&&!dialog.open)dialog.showModal();
    }
  };
})();

'use strict';(()=>{const data=[
