{id:'glacier',name:'Glacier Signature',family:'sport',familyName:'Sport chic',tone:'blue',shape:'angular',strap:'steel',description:'La même silhouette élégante, avec un cadran bleu glacier lumineux.',tags:['Bleu glacier','Acier argenté','Sport chic']},
{id:'minuit',name:'Minuit Classique',family:'classic',familyName:'Classique',tone:'black',shape:'round',strap:'steel',description:'Noir profond et index discrets dans un boîtier aux proportions sobres.',tags:['Noir','Acier','Classique']},
{id:'azur',name:'Azur Classique',family:'classic',familyName:'Classique',tone:'teal',shape:'round',strap:'steel',description:'Bleu nuit et éclats argentés pour un style intemporel.',tags:['Bleu nuit','Métal','Classique']},
{id:'argent',name:'Argent Minimal',family:'minimal',familyName:'Minimaliste',tone:'ivory',shape:'thin',strap:'mesh',description:'Cadran clair et bracelet maille fine au caractère discret.',tags:['Cadran clair','Maille acier','Épurée']},
