];const $=(id)=>document.getElementById(id);const grid=$('styleGrid'),count=$('favCount'),res=$('resultCount'),sum=$('favSummary'),copy=$('copyFav'),feedback=$('copyFeedback'),empty=$('emptyFavourites');if(!grid||!count||!res||!sum||!copy||!empty)return;const key='atelier-style-favs-v1';let fav=new Set(),filter='all';try{const x=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(x))fav=new Set(x.filter(id=>data.some(c=>c.id===id)))}catch(_){ }const make=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n};function card(c){const item=make('article','sel-card'),art=make('div','sel-art '+c.tone);art.setAttribute('role','img');art.setAttribute('aria-label','Illustration fictive du style '+c.name);const band=make('div','sel-strap '+(c.strap==='steel'?'':c.strap));const watch=make('div','sel-watch '+(c.shape==='round'?'':c.shape));watch.append(make('span','sel-center'));art.append(band,watch,make('span','sel-tag','CONCEPT NON COMMERCIALISÉ'));const box=make('div','sel-card-body');box.append(make('p','sel-category',c.familyName),make('h3','',c.name),make('p','desc',c.description));const tags=make('div','sel-tags');c.tags.forEach(t=>tags.append(make('span','',t)));box.append(tags);const btn=make('button','sel-save',fav.has(c.id)?'✓ Retirer des favoris':'♡ Ajouter aux favoris');btn.type='button';btn.setAttribute('aria-pressed',String(fav.has(c.id)));btn.setAttribute('aria-label',(fav.has(c.id)?'Retirer ':'Ajouter ')+c.name+(fav.has(c.id)?' des favoris':' aux favoris'));btn.addEventListener('click',()=>{if(fav.has(c.id))fav.delete(c.id);else fav.add(c.id);try{localStorage.setItem(key,JSON.stringify([...fav]))}catch(_){ }feedback.textContent='';render()});box.append(btn);item.append(art,box);return item}function render(){const visible=data.filter(c=>filter==='all'||(filter==='saved'?fav.has(c.id):c.family===filter));grid.replaceChildren(...visible.map(card));empty.hidden=visible.length>0;count.textC